import { ChangeEvent, DragEvent, useEffect, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Copy, Eye, EyeOff, GripVertical, ImagePlus, Pencil, Plus, Star, Trash2, X } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client'; import { useAuth } from '@/contexts/AuthContext'; import { toast } from 'sonner';

type Image = { id: string; public_url: string; storage_path: string; is_cover: boolean; sort_order: number };
type Addon = { name: string; price: string; description: string };
type Album = { type: string; size: string; pages: string; price: string; is_active: boolean };
type Draft = { id?: string; name: string; price: string; photography_type: string; duration: string; team_size: string; team_custom: string; edited: string; unlimited: boolean; raw: boolean; delivery: string; travel: boolean; radius: string; travelCharge: string; description: string; highlights: string[]; highlightInput: string; status: string; addons: Addon[]; albums: Album[]; files: File[]; images: Image[] };
const TYPES = ['Wedding', 'Pre-wedding', 'Birthday', 'Corporate', 'Portrait', 'Product', 'Other']; const DURATIONS = ['2 hours', '4 hours', '6 hours', '8 hours', 'Full day', 'Custom']; const DELIVERY = ['3-5 days', '7-10 days', '2 weeks', '3 weeks', '4 weeks', 'Custom'];
const blank = (): Draft => ({ name: '', price: '', photography_type: 'Wedding', duration: '', team_size: '1', team_custom: '', edited: '', unlimited: false, raw: false, delivery: '7-10 days', travel: false, radius: '', travelCharge: '', description: '', highlights: [], highlightInput: '', status: 'draft', addons: [], albums: [], files: [], images: [] }); const nullableNum = (v: string) => v === '' ? null : Number(v);
export default function PhotographerPackageManager({ provider }: { provider: any }) {
 const { user } = useAuth(); const qc = useQueryClient(); const [draft, setDraft] = useState<Draft | null>(null); const [busy, setBusy] = useState(false);
 const { data: packages = [], isLoading } = useQuery({ queryKey: ['photography-packages', provider.id], queryFn: async () => { const r = await supabase.from('photography_packages' as any).select('*, photography_package_images(*), photography_package_highlights(*), photography_package_addons(*), photography_albums(*)').eq('photographer_id', provider.id).order('created_at', { ascending: false }); if (r.error) throw r.error; return r.data ?? []; } });
 const refresh = () => qc.invalidateQueries({ queryKey: ['photography-packages', provider.id] });
 useEffect(() => { const channel = supabase.channel(`photographer-packages-${provider.id}`).on('postgres_changes', { event: '*', schema: 'public', table: 'photography_packages', filter: `photographer_id=eq.${provider.id}` }, refresh).on('postgres_changes', { event: '*', schema: 'public', table: 'photography_albums' }, refresh).on('postgres_changes', { event: '*', schema: 'public', table: 'photography_package_images' }, refresh).subscribe(); return () => { supabase.removeChannel(channel); }; }, [provider.id]);
 const edit = (p: any) => setDraft({ id: p.id, name: p.name, price: String(p.price), photography_type: p.photography_type || 'Wedding', duration: p.duration || '', team_size: p.team_size === 0 ? 'custom' : String(p.team_size ?? 1), team_custom: String(p.team_size_custom ?? ''), edited: String(p.edited_photos ?? ''), unlimited: p.edited_photos === null, raw: !!p.raw_photos_included, delivery: p.delivery_time || '7-10 days', travel: !!p.travel_included, radius: String(p.travel_radius_km ?? ''), travelCharge: String(p.travel_extra_charge ?? ''), description: p.description || '', highlights: (p.photography_package_highlights ?? []).map((h: any) => h.text), highlightInput: '', status: p.status || 'draft', addons: (p.photography_package_addons ?? []).map((a: any) => ({ name: a.name, price: String(a.price), description: a.description || '' })), albums: (p.photography_albums ?? []).map((a: any) => ({ type: a.type, size: a.size, pages: String(a.pages), price: String(a.price), is_active: a.is_active })), files: [], images: [...(p.photography_package_images ?? [])].sort((a: any, b: any) => a.sort_order - b.sort_order) });
 const upload = async (id: string, files: File[]) => { if (!user) return; for (const [i, file] of files.entries()) { if (!file.type.startsWith('image/') || file.size > 8 * 1024 * 1024) throw new Error('Use image files under 8MB'); const path = `${user.id}/${id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, '_')}`; const up = await supabase.storage.from('photography-package-images').upload(path, file, { contentType: file.type }); if (up.error) throw up.error; const url = supabase.storage.from('photography-package-images').getPublicUrl(path).data.publicUrl; const result = await supabase.from('photography_package_images' as any).insert({ package_id: id, storage_path: path, public_url: url, alt_text: file.name, is_cover: i === 0 && !draft?.images.length, sort_order: (draft?.images.length ?? 0) + i }); if (result.error) throw result.error; } };
 const save = async () => { if (!draft || !draft.name.trim() || draft.price === '' || !draft.duration || !draft.delivery || (draft.team_size === 'custom' && (!draft.team_custom || Number(draft.team_custom) < 1)) || (!draft.unlimited && (draft.edited === '' || Number(draft.edited) < 0))) return toast.error('Complete the required package, team and edited-photo fields.'); setBusy(true); try { const d = draft; const payload = { photographer_id: provider.id, name: d.name.trim(), price: Number(d.price), photography_type: d.photography_type, duration: d.duration, team_size: d.team_size === 'custom' ? 0 : Number(d.team_size), team_size_custom: d.team_size === 'custom' ? Number(d.team_custom) : null, edited_photos: d.unlimited ? null : Number(d.edited), raw_photos_included: d.raw, delivery_time: d.delivery, travel_included: d.travel, travel_radius_km: d.travel ? nullableNum(d.radius) : null, travel_extra_charge: d.travel ? nullableNum(d.travelCharge) : null, description: d.description.trim() || null, status: d.status, is_active: d.status !== 'archived', is_visible: d.status === 'published', album_included: false, album_type: null, album_size: null, album_pages: null }; const r = d.id ? await supabase.from('photography_packages' as any).update(payload).eq('id', d.id).select().single() : await supabase.from('photography_packages' as any).insert(payload).select().single(); if (r.error) throw r.error; const id = r.data.id; if (d.id) { await Promise.all(['photography_package_highlights', 'photography_package_addons', 'photography_albums'].map(table => supabase.from(table as any).delete().eq('package_id', id))); } if (d.highlights.length) { const e = await supabase.from('photography_package_highlights' as any).insert(d.highlights.map((text, sort_order) => ({ package_id: id, text, sort_order }))); if (e.error) throw e.error; } const addons = d.addons.filter(a => a.name.trim() && a.price !== '').map((a, sort_order) => ({ package_id: id, name: a.name.trim(), price: Number(a.price), description: a.description.trim() || null, sort_order })); if (addons.length) { const e = await supabase.from('photography_package_addons' as any).insert(addons); if (e.error) throw e.error; } const albums = d.albums.filter(a => a.type.trim() && a.size.trim() && a.pages && a.price !== '').map((a, sort_order) => ({ package_id: id, type: a.type.trim(), size: a.size.trim(), pages: Number(a.pages), price: Number(a.price), is_active: a.is_active, sort_order })); if (albums.length) { const e = await supabase.from('photography_albums' as any).insert(albums); if (e.error) throw e.error; } await upload(id, d.files); toast.success('Photography package saved'); setDraft(null); refresh(); } catch (e: any) { toast.error(e.message || 'Could not save package'); } finally { setBusy(false); } };
 const updateImageOrder = async (images: Image[]) => { if (!draft?.id) return; const updates = images.map((image, sort_order) => supabase.from('photography_package_images' as any).update({ sort_order }).eq('id', image.id)); const result = await Promise.all(updates); const error = result.find((r: any) => r.error)?.error; if (error) toast.error(error.message); else { setDraft({ ...draft, images }); refresh(); } };
 const setCover = async (image: Image) => { if (!draft?.id) return; const off = await supabase.from('photography_package_images' as any).update({ is_cover: false }).eq('package_id', draft.id); const on = !off.error && await supabase.from('photography_package_images' as any).update({ is_cover: true }).eq('id', image.id); if (off.error || (on as any)?.error) return toast.error(off.error?.message || (on as any).error.message); setDraft({ ...draft, images: draft.images.map(x => ({ ...x, is_cover: x.id === image.id })) }); };
 const removeImage = async (image: Image) => { if (!confirm('Remove this image?')) return; const r = await supabase.from('photography_package_images' as any).delete().eq('id', image.id); if (r.error) return toast.error(r.error.message); await supabase.storage.from('photography-package-images').remove([image.storage_path]); setDraft(d => d && ({ ...d, images: d.images.filter(x => x.id !== image.id) })); };
 return <div className="max-w-[1200px] space-y-6"><div className="flex justify-between gap-3"><div><h1 className="text-xl font-bold">Photography Packages</h1><p className="text-sm text-muted-foreground">Create customer-ready photography packages and optional upgrades.</p></div><button onClick={() => setDraft(blank())} className="rounded-xl bg-[#8B1538] px-4 py-2.5 text-sm font-semibold text-white"><Plus className="mr-1 inline h-4" />Create package</button></div>{isLoading ? <div className="h-48 animate-pulse rounded-2xl bg-muted" /> : <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{packages.map((p: any) => { const image = p.photography_package_images?.find((x: any) => x.is_cover) ?? p.photography_package_images?.[0]; return <div key={p.id} className="overflow-hidden rounded-2xl border bg-white"><div className="h-36 bg-secondary">{image && <img src={image.public_url} alt="" className="h-full w-full object-cover" />}</div><div className="p-4"><div className="flex justify-between"><h2 className="font-bold">{p.name}</h2><span className="text-xs uppercase">{p.status}</span></div><p className="font-bold">₹{Number(p.price).toLocaleString('en-IN')}</p><p className="text-xs text-muted-foreground">{p.photography_type} · {p.duration} · {p.team_size_custom || p.team_size} team</p><div className="mt-4 flex gap-2"><button onClick={() => edit(p)} className="flex-1 rounded-lg border py-2 text-xs"><Pencil className="mr-1 inline h-3" />Edit</button><button onClick={() => supabase.from('photography_packages' as any).insert({ photographer_id: provider.id, name: `${p.name} (Copy)`, price: p.price, photography_type: p.photography_type, duration: p.duration, team_size: p.team_size, status: 'draft', is_visible: false, is_active: true }).then(refresh)} className="rounded-lg border p-2"><Copy className="h-3" /></button><button onClick={() => supabase.from('photography_packages' as any).update({ status: p.status === 'published' ? 'draft' : 'published', is_visible: p.status !== 'published' }).eq('id', p.id).then(refresh)} className="rounded-lg border p-2">{p.status === 'published' ? <EyeOff className="h-3" /> : <Eye className="h-3" />}</button><button onClick={() => confirm('Delete this package?') && supabase.from('photography_packages' as any).delete().eq('id', p.id).then(refresh)} className="rounded-lg border p-2 text-red-600"><Trash2 className="h-3" /></button></div></div></div>; })}</div>}{draft && <Editor d={draft} patch={(v: Partial<Draft>) => setDraft(old => old && ({ ...old, ...v }))} close={() => setDraft(null)} save={save} busy={busy} setCover={setCover} removeImage={removeImage} updateImageOrder={updateImageOrder} />}</div>;
}
function Editor({ d, patch, close, save, busy, setCover, removeImage, updateImageOrder }: any) { const addFiles = (files: FileList | File[]) => patch({ files: [...d.files, ...Array.from(files)] }); const addHighlight = () => { const text = d.highlightInput.trim(); if (text && !d.highlights.includes(text)) patch({ highlights: [...d.highlights, text], highlightInput: '' }); }; const field = (label: string, child: any) => <label className="block text-sm font-medium">{label}<div className="mt-1 [&_input]:w-full [&_input]:rounded-lg [&_input]:border [&_input]:p-2 [&_select]:w-full [&_select]:rounded-lg [&_select]:border [&_select]:p-2 [&_textarea]:w-full [&_textarea]:rounded-lg [&_textarea]:border [&_textarea]:p-2">{child}</div></label>; return <div className="fixed inset-0 z-[70] overflow-y-auto bg-black/50 p-4"><div className="mx-auto max-w-4xl space-y-5 rounded-2xl bg-white p-6"><div className="flex justify-between"><h2 className="font-bold">{d.id ? 'Edit' : 'Create'} photography package</h2><button onClick={close}><X /></button></div><section><h3 className="font-semibold">Basic Information</h3><div className="mt-2 grid gap-3 sm:grid-cols-2">{field('Package name *', <input value={d.name} onChange={e => patch({ name: e.target.value })} />)}{field('Package price (₹) *', <input type="number" min="0" value={d.price} onChange={e => patch({ price: e.target.value })} />)}{field('Photography type *', <select value={d.photography_type} onChange={e => patch({ photography_type: e.target.value })}>{TYPES.map(x => <option key={x}>{x}</option>)}</select>)}{field('Duration *', <select value={d.duration} onChange={e => patch({ duration: e.target.value })}><option value="">Select duration</option>{DURATIONS.map(x => <option key={x}>{x}</option>)}</select>)}</div></section><section><h3 className="font-semibold">Package Features</h3><div className="mt-2 grid gap-3 sm:grid-cols-2">{field('Team size *', <select value={d.team_size} onChange={e => patch({ team_size: e.target.value })}>{['1', '2', '3', '4', 'custom'].map(x => <option key={x} value={x}>{x === 'custom' ? 'Custom' : `${x} member${x === '1' ? '' : 's'}`}</option>)}</select>)}{d.team_size === 'custom' && field('Custom team size *', <input type="number" min="1" value={d.team_custom} onChange={e => patch({ team_custom: e.target.value })} />)}{field('Delivery time *', <select value={d.delivery} onChange={e => patch({ delivery: e.target.value })}>{DELIVERY.map(x => <option key={x}>{x}</option>)}</select>)}{field('Edited photos *', <input disabled={d.unlimited} type="number" min="0" value={d.edited} onChange={e => patch({ edited: e.target.value })} placeholder="Number of edited photos" />)}</div><div className="mt-2 flex flex-wrap gap-4 text-sm"><label><input type="checkbox" checked={d.unlimited} onChange={e => patch({ unlimited: e.target.checked, edited: e.target.checked ? '' : d.edited })} /> Unlimited edited photos</label><label><input type="checkbox" checked={d.raw} onChange={e => patch({ raw: e.target.checked })} /> Raw photos included</label><label><input type="checkbox" checked={d.travel} onChange={e => patch({ travel: e.target.checked })} /> Travel included</label></div>{d.travel && <div className="mt-3 grid gap-3 sm:grid-cols-2">{field('Included radius (km)', <input type="number" min="0" value={d.radius} onChange={e => patch({ radius: e.target.value })} />)}{field('Extra charge beyond radius (₹)', <input type="number" min="0" value={d.travelCharge} onChange={e => patch({ travelCharge: e.target.value })} />)}</div>}</section><section><h3 className="font-semibold">Highlights</h3><div className="mt-2 flex gap-2"><input className="flex-1 rounded-lg border p-2" value={d.highlightInput} onChange={e => patch({ highlightInput: e.target.value })} onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addHighlight())} placeholder="Type a highlight and press Enter" /><button type="button" onClick={addHighlight} className="rounded-lg border px-3">Add</button></div><div className="mt-2 flex flex-wrap gap-2">{d.highlights.map((h: string) => <span key={h} className="rounded-full bg-secondary px-2 py-1 text-xs">{h}<button onClick={() => patch({ highlights: d.highlights.filter((x: string) => x !== h) })} className="ml-1"><X className="inline h-3" /></button></span>)}</div></section><section><h3 className="font-semibold">Images</h3><div onDragOver={e => e.preventDefault()} onDrop={(e: DragEvent) => { e.preventDefault(); addFiles(e.dataTransfer.files); }} className="mt-2 rounded-xl border-2 border-dashed p-5 text-center text-sm"><ImagePlus className="mx-auto mb-2 h-5" />Drag images here or <label className="cursor-pointer font-semibold text-[#8B1538]">browse<input className="hidden" type="file" accept="image/*" multiple onChange={(e: ChangeEvent<HTMLInputElement>) => addFiles(e.target.files ?? [])} /></label><p className="mt-1 text-xs text-muted-foreground">Image files up to 8MB. Drag cards to reorder.</p></div><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4">{d.images.map((im: Image, i: number) => <div key={im.id} draggable onDragStart={(e: any) => e.dataTransfer.setData('image-index', String(i))} onDrop={(e: any) => { const from = Number(e.dataTransfer.getData('image-index')); if (from !== i) { const next = [...d.images]; const [moved] = next.splice(from, 1); next.splice(i, 0, moved); updateImageOrder(next); } }} onDragOver={(e: any) => e.preventDefault()} className="relative overflow-hidden rounded-lg border"><img src={im.public_url} className="h-24 w-full object-cover" alt="Package" /><div className="absolute inset-x-0 bottom-0 flex justify-between bg-black/60 p-1 text-[10px] text-white"><GripVertical className="h-3" /><button onClick={() => setCover(im)}>{im.is_cover ? <Star className="h-3 fill-current" /> : 'Cover'}</button><button onClick={() => removeImage(im)}>Delete</button></div></div>)}{d.files.map((f: File, i: number) => <div key={f.name + i} className="relative"><img src={URL.createObjectURL(f)} className="h-24 w-full rounded-lg object-cover" alt="New package preview" /><button onClick={() => patch({ files: d.files.filter((_: File, j: number) => j !== i) })} className="absolute right-1 top-1 rounded bg-black/60 p-1 text-white"><X className="h-3" /></button></div>)}</div></section><section><h3 className="font-semibold">Add-ons</h3><Rows rows={d.addons} defaults={{ name: '', price: '', description: '' }} labels={['Name', 'Price (₹)', 'Description']} onChange={(addons: Addon[]) => patch({ addons })} /></section><section><h3 className="font-semibold">Optional albums</h3><p className="text-xs text-muted-foreground">Customers choose an album only if they want one; it is never included in the package price.</p><Rows rows={d.albums} defaults={{ type: '', size: '', pages: '', price: '', is_active: true }} labels={['Type', 'Size', 'Pages', 'Price (₹)']} onChange={(albums: Album[]) => patch({ albums })} /></section><section><h3 className="font-semibold">Preview</h3><div className="mt-2 rounded-xl bg-secondary p-4"><div className="flex justify-between"><b>{d.name || 'Your package name'}</b><b>₹{d.price || '0'}</b></div><p className="text-sm">{d.photography_type} · {d.duration || 'Duration'} · {d.team_size === 'custom' ? d.team_custom : d.team_size} team · {d.unlimited ? 'Unlimited' : d.edited || '0'} edited photos</p><p className="text-sm">Delivery: {d.delivery}{d.travel && ` · Travel included within ${d.radius || 0} km`}</p><div className="mt-2 flex flex-wrap gap-1">{d.highlights.map((h: string) => <span key={h} className="rounded-full bg-white px-2 py-1 text-xs">{h}</span>)}</div>{d.albums.length > 0 && <p className="mt-2 text-sm">Optional albums from ₹{Math.min(...d.albums.filter((a: Album) => a.price !== '').map((a: Album) => Number(a.price))) || 0}</p>}</div></section>{field('Status', <select value={d.status} onChange={e => patch({ status: e.target.value })}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select>)}<div className="flex gap-3"><button onClick={close} className="flex-1 rounded-xl border py-2.5">Cancel</button><button disabled={busy} onClick={save} className="flex-1 rounded-xl bg-[#8B1538] py-2.5 text-white">{busy ? 'Saving…' : 'Save package'}</button></div></div></div>; }
function Rows({ rows, defaults, labels, onChange }: any) { const keys = Object.keys(defaults).filter(k => k !== 'is_active'); return <div className="mt-2 space-y-2">{rows.map((row: any, i: number) => <div key={i} className="flex flex-wrap gap-2">{keys.map(k => <input key={k} type={k === 'price' || k === 'pages' ? 'number' : 'text'} min="0" className="min-w-[110px] flex-1 rounded-lg border p-2 text-sm" placeholder={labels[keys.indexOf(k)]} value={row[k]} onChange={e => onChange(rows.map((x: any, j: number) => j === i ? { ...x, [k]: e.target.value } : x))} />)}{'is_active' in defaults && <label className="text-xs"><input type="checkbox" checked={row.is_active} onChange={e => onChange(rows.map((x: any, j: number) => j === i ? { ...x, is_active: e.target.checked } : x))} /> Active</label>}<button onClick={() => onChange(rows.filter((_: any, j: number) => j !== i))}><Trash2 className="h-4 text-red-600" /></button></div>)}<button type="button" onClick={() => onChange([...rows, defaults])} className="text-xs font-bold text-[#8B1538]"><Plus className="mr-1 inline h-3" />Add {labels[0].toLowerCase()}</button></div>; }
